// Extract custom fields from ClickUp task
const task = $input.first().json;
const customFields = task.custom_fields || [];

function getFieldValue(fields, fieldName) {
  const field = fields.find(f => f.name === fieldName);
  if (!field) return '';
  // Text fields
  if (field.type === 'short_text' || field.type === 'text' || field.type === 'url') {
    return field.value || '';
  }
  // Drop-down fields
  if (field.type === 'drop_down' && field.type_config && field.type_config.options) {
    const selected = field.type_config.options.find(o => o.orderindex === field.value);
    return selected ? selected.name : '';
  }
  return field.value || '';
}

const googleDocUrl = getFieldValue(customFields, 'Link zum Beitrag');
const metaTitle = getFieldValue(customFields, 'Meta Title');
const metaDescription = getFieldValue(customFields, 'Meta Description');
const themenCluster = getFieldValue(customFields, 'Themen-Cluster');

// Extract Google Doc ID from URL
// Format: https://docs.google.com/document/d/DOC_ID/edit
let googleDocId = '';
if (googleDocUrl) {
  const match = googleDocUrl.match(/\/document\/d\/([a-zA-Z0-9_-]+)/);
  if (match) {
    googleDocId = match[1];
  }
}

// Extract featured image URL from task description if present
let featuredImageUrl = '';
if (task.description) {
  const imgMatch = task.description.match(/!\[.*?\]\((https?:\/\/[^)]+)\)/);
  if (imgMatch) {
    featuredImageUrl = imgMatch[1];
  } else {
    const urlMatch = task.description.match(/(https?:\/\/[^\s]+\.(?:jpg|jpeg|png|gif|webp))/i);
    if (urlMatch) {
      featuredImageUrl = urlMatch[1];
    }
  }
}

return [{
  json: {
    task_id: task.id,
    task_name: task.name,
    google_doc_url: googleDocUrl,
    google_doc_id: googleDocId,
    meta_title: metaTitle,
    meta_description: metaDescription,
    themen_cluster: themenCluster,
    featured_image_url: featuredImageUrl
  }
}];

// Convert Google Docs JSON content to clean HTML for WordPress
const doc = $input.first().json;
const content = doc.body?.content || [];

let html = '';
let listStack = [];

function getTextStyle(style) {
  let prefix = '';
  let suffix = '';
  if (style?.bold) { prefix += '<strong>'; suffix = '</strong>' + suffix; }
  if (style?.italic) { prefix += '<em>'; suffix = '</em>' + suffix; }
  if (style?.underline) { prefix += '<u>'; suffix = '</u>' + suffix; }
  if (style?.strikethrough) { prefix += '<del>'; suffix = '</del>' + suffix; }
  return { prefix, suffix };
}

function escapeHtml(text) {
  return text
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');
}

for (const element of content) {
  if (element.paragraph) {
    const para = element.paragraph;
    const style = para.paragraphStyle?.namedStyleType || 'NORMAL_TEXT';
    let text = '';

    for (const elem of (para.elements || [])) {
      if (elem.textRun) {
        const ts = getTextStyle(elem.textRun.textStyle || {});
        let runText = escapeHtml(elem.textRun.content || '');

        // Handle links
        if (elem.textRun.textStyle?.link?.url) {
          const url = elem.textRun.textStyle.link.url;
          runText = `<a href="${url}">${runText}</a>`;
        }

        text += ts.prefix + runText + ts.suffix;
      }
      if (elem.inlineObjectElement) {
        // Inline images - reference by object ID
        const objId = elem.inlineObjectElement.inlineObjectId;
        const inlineObj = doc.inlineObjects?.[objId];
        if (inlineObj) {
          const imgProps = inlineObj.inlineObjectProperties?.embeddedObject;
          if (imgProps?.imageProperties?.contentUri) {
            const alt = imgProps.title || imgProps.description || '';
            text += `<img src="${imgProps.imageProperties.contentUri}" alt="${escapeHtml(alt)}" />`;
          }
        }
      }
    }

    // Trim trailing newline
    text = text.replace(/\n$/, '');

    if (!text.trim()) {
      continue;
    }

    // Handle list items
    if (para.bullet) {
      const listId = para.bullet.listId;
      const nestingLevel = para.bullet.nestingLevel || 0;
      const listType = doc.lists?.[listId]?.listProperties?.nestingLevels?.[nestingLevel]?.glyphType
        ? 'ol' : 'ul';

      if (listStack.length === 0 || listStack[listStack.length - 1].listId !== listId) {
        html += `<${listType}>`;
        listStack.push({ listId, type: listType });
      }
      html += `<li>${text}</li>`;
      continue;
    }

    // Close any open lists
    while (listStack.length > 0) {
      const last = listStack.pop();
      html += `</${last.type}>`;
    }

    // Map heading styles
    switch (style) {
      case 'HEADING_1':
        html += `<h1>${text}</h1>`;
        break;
      case 'HEADING_2':
        html += `<h2>${text}</h2>`;
        break;
      case 'HEADING_3':
        html += `<h3>${text}</h3>`;
        break;
      case 'HEADING_4':
        html += `<h4>${text}</h4>`;
        break;
      case 'HEADING_5':
        html += `<h5>${text}</h5>`;
        break;
      case 'HEADING_6':
        html += `<h6>${text}</h6>`;
        break;
      default:
        html += `<p>${text}</p>`;
        break;
    }
  }

  if (element.table) {
    html += '<table>';
    for (const row of (element.table.tableRows || [])) {
      html += '<tr>';
      for (const cell of (row.tableCells || [])) {
        let cellText = '';
        for (const cp of (cell.content || [])) {
          if (cp.paragraph) {
            for (const elem of (cp.paragraph.elements || [])) {
              if (elem.textRun) {
                cellText += escapeHtml(elem.textRun.content || '').replace(/\n$/, '');
              }
            }
          }
        }
        html += `<td>${cellText}</td>`;
      }
      html += '</tr>';
    }
    html += '</table>';
  }
}

// Close remaining open lists
while (listStack.length > 0) {
  const last = listStack.pop();
  html += `</${last.type}>`;
}

return [{
  json: {
    html_content: html
  }
}];

const categories = $input.first().json;
const themenCluster = $('Extract Data').item.json.themen_cluster;

// Check if exact match exists
let categoryId = null;
if (Array.isArray(categories)) {
  const match = categories.find(
    c => c.name.toLowerCase() === themenCluster.toLowerCase()
  );
  if (match) {
    categoryId = match.id;
  }
}

return [{
  json: {
    category_id: categoryId,
    category_name: themenCluster,
    needs_creation: categoryId === null
  }
}];

// Merge category ID from either the existing lookup or the newly created category
const checkNode = $('Check Category Exists').item.json;
const ifNode = $('Category Exists?');

let categoryId;
try {
  // If category was created
  const created = $input.first().json;
  categoryId = created.id || checkNode.category_id;
} catch (e) {
  categoryId = checkNode.category_id;
}

return [{
  json: {
    category_id: categoryId
  }
}];

// Pass through existing category ID
const checkNode = $('Check Category Exists').item.json;

return [{
  json: {
    category_id: checkNode.category_id
  }
}];

// Determine the category_id from whichever branch ran
let categoryId = null;

try {
  const created = $('Merge Category ID (Created)').item.json;
  if (created && created.category_id) categoryId = created.category_id;
} catch(e) {}

if (!categoryId) {
  try {
    const existing = $('Merge Category ID (Existing)').item.json;
    if (existing && existing.category_id) categoryId = existing.category_id;
  } catch(e) {}
}

return [{
  json: {
    category_id: categoryId
  }
}];

// Generate 2 featured images with Gemini
const geminiKey = $('Config').item.json.gemini_api_key;
const taskName = $('Extract Data').item.json.task_name;
const htmlContent = $('Convert Doc to HTML').item.json.html_content || '';

// Strip HTML to plain text (first 3000 chars)
const plainText = htmlContent.replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim().substring(0, 3000);

if (!geminiKey) {
  return [{ json: { featured_media_id: 0, error: 'Kein GEMINI_API_KEY gesetzt' } }];
}

// Step 1: Ask Gemini Flash to analyze the article and create a scene description
const analysisResponse = await this.helpers.httpRequest({
  method: 'POST',
  url: `https://generativelanguage.googleapis.com/v1beta/models/gemini-2.0-flash:generateContent?key=${geminiKey}`,
  headers: { 'Content-Type': 'application/json' },
  body: JSON.stringify({
    contents: [{
      parts: [{
        text: `Analysiere den folgenden Blogartikel und erstelle eine Bildbeschreibung f\u00fcr ein Titelbild.\n\nArtikel-Titel: ${taskName}\n\nArtikel-Inhalt (Auszug):\n${plainText}\n\nAntworte NUR mit einem JSON-Objekt:\n{\n  "topic": "Thema in einem kurzen Satz",\n  "scene_description_1": "Detaillierte visuelle Beschreibung einer realen Szene f\u00fcr Foto-Variante 1. 2-3 S\u00e4tze. Beschreibe Personen, Objekte, Umgebung, Tageszeit.",\n  "scene_description_2": "Detaillierte visuelle Beschreibung einer ANDEREN realen Szene f\u00fcr Foto-Variante 2 (andere Perspektive/Situation, aber gleiches Thema). 2-3 S\u00e4tze.",\n  "core_message": "1-2 S\u00e4tze, was der Artikel inhaltlich vermittelt"\n}`
      }]
    }],
    generationConfig: { temperature: 0.7 }
  }),
  returnFullResponse: false
});

let analysis;
try {
  const text = analysisResponse.candidates[0].content.parts[0].text;
  const jsonMatch = text.match(/\{[\s\S]*\}/);
  analysis = JSON.parse(jsonMatch[0]);
} catch(e) {
  analysis = {
    topic: taskName,
    scene_description_1: `Ein professionelles Foto das das Thema ${taskName} zeigt`,
    scene_description_2: `Eine alternative Szene zum Thema ${taskName} aus anderer Perspektive`,
    core_message: `Informationen zum Thema ${taskName}`
  };
}

// Step 2: Build 2 image prompts using the user's template
function buildPrompt(topic, sceneDesc, coreMessage) {
  return `Erzeuge ein ultra-fotorealistisches Foto, das so wirkt, als w\u00e4re es mit einem aktuellen iPhone-Smartphone aufgenommen worden, direkt aus der Hand, ohne Filter.\nZweck: Das Foto ist Titelbild f\u00fcr einen Blogbeitrag mit dem Thema: \u201e${topic}\u201c. Die Szene soll den Inhalt des Beitrags m\u00f6glichst exakt darstellen, so dass man das Thema des Textes intuitiv erkennt.\nKamera-Stil:\n* Captured with a modern iPhone smartphone camera, handheld, native camera app.\n* Leichtes, realistisches Bildrauschen in den Schatten, nat\u00fcrliche Sch\u00e4rfe, keine \u00fcbertriebene Klarheit.\n* Automatischer Wei\u00dfabgleich, automatische Belichtung, Look wie ein echtes Handyfoto.\n* Keine sichtbare Tiefensch\u00e4rfe-Simulation wie Studio-Portrait, sondern authentische Handy-Optik.\nPerspektive / Komposition:\n* Aufnahmeposition: Augenh\u00f6he oder leicht dar\u00fcber, als w\u00fcrde eine reale Person die Szene mit einem iPhone fotografieren.\n* Leicht unperfekte, menschliche Komposition: minimal schiefer Horizont oder kleine Abweichung von perfekter Symmetrie, um Realismus zu erh\u00f6hen.\n* Bildformat 16:9 (ideal als Titelbild).\nSzene / Inhalt (an Beitrag angepasst):\n* Zeige folgende Situation: ${sceneDesc}\n* Die Szene soll exakt die Kernaussage des Blogartikels vermitteln: ${coreMessage}\n* Umgebung realistisch und glaubw\u00fcrdig: nat\u00fcrlicher Raum, echte M\u00f6bel, glaubw\u00fcrdige Alltagsobjekte.\nLicht / Atmosph\u00e4re:\n* Nat\u00fcrliches Innenlicht oder Tageslicht durch ein Fenster, wie bei einem spontan aufgenommenen Foto im B\u00fcro/zu Hause.\n* Realistische Belichtung, leichte \u00dcberbelichtung in Highlights und minimaler Rauschteppich in dunklen Bereichen, wie bei einem Handyfoto.\n* Keine dramatischen Kino-Licht-Setups, sondern Alltagssituation.\nStil & Qualit\u00e4t:\n* Ultra photorealistic, aber mit der leichten Unsch\u00e4rfe und Sch\u00e4rfentiefe einer modernen Smartphone-Kamera.\n* Farben nat\u00fcrlich, moderat ges\u00e4ttigt, kein \u00fcbertriebener HDR-Look, kein Beauty-Filter.\n* Bild soll wirken wie ein authentisches Foto, das jemand spontan f\u00fcr einen Blog gemacht hat, aber mit sehr sauberer Komposition.\nNegative Vorgaben:\n* Kein sichtbares Wasserzeichen, kein Text im Bild, keine Logos von Marken, kein sichtbares iPhone-Geh\u00e4use.\n* Kein Kunst-Look, keine Illustration, kein 3D-Render, kein Comic-Stil.\n* Keine unrealistischen Effekte, keine Lens-Flares, kein \u00fcbertriebener Bokeh-Effekt.`;
}

const prompt1 = buildPrompt(analysis.topic, analysis.scene_description_1, analysis.core_message);
const prompt2 = buildPrompt(analysis.topic, analysis.scene_description_2, analysis.core_message);

// Step 3: Generate both images
async function generateImage(prompt) {
  try {
    const resp = await this.helpers.httpRequest({
      method: 'POST',
      url: `https://generativelanguage.googleapis.com/v1beta/models/gemini-2.0-flash-exp:generateContent?key=${geminiKey}`,
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        contents: [{ parts: [{ text: prompt }] }],
        generationConfig: { responseModalities: ['IMAGE', 'TEXT'] }
      }),
      returnFullResponse: false,
      timeout: 120000
    });
    const parts = resp.candidates?.[0]?.content?.parts || [];
    const imgPart = parts.find(p => p.inlineData);
    if (imgPart) {
      return { data: imgPart.inlineData.data, mimeType: imgPart.inlineData.mimeType || 'image/png' };
    }
  } catch(e) {
    // Fallback: try imagen-3.0-generate-002
    try {
      const resp2 = await this.helpers.httpRequest({
        method: 'POST',
        url: `https://generativelanguage.googleapis.com/v1beta/models/imagen-3.0-generate-002:predict?key=${geminiKey}`,
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          instances: [{ prompt: prompt }],
          parameters: { sampleCount: 1, aspectRatio: '16:9', personGeneration: 'allow_all' }
        }),
        returnFullResponse: false,
        timeout: 120000
      });
      if (resp2.predictions?.[0]?.bytesBase64Encoded) {
        return { data: resp2.predictions[0].bytesBase64Encoded, mimeType: resp2.predictions[0].mimeType || 'image/png' };
      }
    } catch(e2) {}
  }
  return null;
}

const [img1, img2] = await Promise.all([
  generateImage.call(this, prompt1),
  generateImage.call(this, prompt2)
]);

// Prepare binary outputs
const result = { json: { image_count: 0, analysis: analysis } };
const binaries = {};

if (img1) {
  const ext = img1.mimeType.includes('jpeg') ? 'jpg' : 'png';
  binaries.image1 = await this.helpers.prepareBinaryData(
    Buffer.from(img1.data, 'base64'),
    `featured-image-1.${ext}`,
    img1.mimeType
  );
  result.json.image_count++;
}

if (img2) {
  const ext = img2.mimeType.includes('jpeg') ? 'jpg' : 'png';
  binaries.image2 = await this.helpers.prepareBinaryData(
    Buffer.from(img2.data, 'base64'),
    `featured-image-2.${ext}`,
    img2.mimeType
  );
  result.json.image_count++;
}

result.binary = binaries;
return [result];

// Extract the media ID from the uploaded image
try {
  const media = $input.first().json;
  return [{ json: { featured_media_id: media.id || 0 } }];
} catch(e) {
  return [{ json: { featured_media_id: 0 } }];
}

